//! Agents: the list and one agent. Generated by `cargo offrails generate resource agents name:string description:text`.

use axum::http::StatusCode;
use board::routes::paths;

use crate::factories;
use crate::support::TestApp;

#[tokio::test]
async fn index_lists_agents() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let record = factories::agent(app.db(), &me).await;
    app.get(&paths::agents())
        .await
        .assert_ok()
        .assert_text(&record.label());
}

#[tokio::test]
async fn index_runs_the_same_queries_for_1_or_20_agents() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    app.assert_query_count_stable(&paths::agents(), async |count| {
        for _ in 0..count {
            factories::agent(app.db(), &me).await;
        }
    })
    .await;
}

/// A page past the last one (or a huge `?page=`) is an empty list, never a 500.
#[tokio::test]
async fn a_page_past_the_end_is_empty() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    for page in ["2", "18446744073709551615"] {
        app.get(&format!("{}?page={page}", paths::agents()))
            .await
            .assert_ok();
    }
}

#[tokio::test]
async fn show_renders_a_agent() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let record = factories::agent(app.db(), &me).await;
    app.get(&paths::agent(record.id))
        .await
        .assert_ok()
        .assert_text(&record.label());
    app.get(&paths::agent(record.id + 1000))
        .await
        .assert_status(StatusCode::NOT_FOUND);
}
